import React from "react";

const Sidebar = () => {
  return (
    <div style={{
      width: "200px",
      height: "100vh",
      backgroundColor: "#1e1e2f",
      color: "white",
      padding: "20px"
    }}>
      <h2>Budget</h2>
      <p>Dashboard</p>
      <p>Transactions</p>
      <p>Settings</p>
    </div>
  );
};

export default Sidebar;
